  <style>
    :root {
      --navy:#16345b; --navy-dark:#102846; --blue:#2367a6; --teal:#1f9a9c; --gold:#d7a642;
      --ink:#182231; --muted:#647286; --line:#d8e0ea; --soft:#f3f7fa; --white:#fff;
      --good:#287a55; --warn:#946714; --risk:#b54343;
      font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
    }
    *{box-sizing:border-box} body{margin:0;color:var(--ink);background:#eef3f7}.shell{display:grid;grid-template-columns:292px 1fr;min-height:100vh}
    .sidebar{position:sticky;top:0;height:100vh;padding:20px 16px;color:#fff;background:linear-gradient(180deg,var(--navy),var(--navy-dark));overflow:auto}
    .brand{display:flex;align-items:center;gap:12px;padding:4px 8px 20px}.brand img{width:48px;height:48px;object-fit:contain;border-radius:8px;background:#fff}.brand strong,.brand span{display:block}.brand strong{font-size:15px}.brand span{margin-top:3px;color:#c8d7e7;font-size:11px}
    .nav{display:grid;gap:6px}.nav a{display:flex;align-items:center;gap:11px;min-height:42px;padding:10px 12px;border-radius:8px;color:#dce8f3;text-decoration:none;font-size:13px;font-weight:750}.nav a::before{content:attr(data-icon);display:grid;place-items:center;width:23px;height:23px;border-radius:7px;background:rgba(255,255,255,.08)}.nav a:hover,.nav a.active{color:#fff;background:rgba(255,255,255,.12);box-shadow:inset 3px 0 0 var(--gold)}
    .side-note{margin-top:18px;padding:14px;border:1px solid rgba(255,255,255,.13);border-radius:9px;color:#c8d7e7;background:rgba(255,255,255,.06);font-size:11px;line-height:1.55}
    .main{min-width:0}.topbar{min-height:88px;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px 28px;border-bottom:1px solid var(--line);background:#fff}.topbar h1{margin:0;color:var(--navy);font-size:24px}.topbar p{margin:5px 0 0;color:var(--muted);font-size:13px}.draft{padding:7px 11px;border:1px solid rgba(215,166,66,.38);border-radius:999px;color:#805a10;background:#fff5dc;font-size:11px;font-weight:850;text-transform:uppercase;letter-spacing:.04em}
    .content{display:grid;gap:18px;padding:24px 28px 38px}.panel{padding:21px;border:1px solid var(--line);border-radius:11px;background:#fff;box-shadow:0 9px 28px rgba(22,52,91,.06)}.panel h2{margin:0;color:var(--navy);font-size:19px}.panel-intro{max-width:880px;margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.6}
    .notice{display:grid;grid-template-columns:38px 1fr;gap:12px;align-items:start;padding:15px;border:1px solid #cdddea;border-radius:10px;background:linear-gradient(135deg,#edf5fb,#f9fcfe)}.notice-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;color:#fff;background:var(--blue);font-weight:900}.notice strong{display:block;color:var(--navy);font-size:13px}.notice p{margin:4px 0 0;color:#52657a;font-size:12px;line-height:1.5}
    .role-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:17px}.role-card{position:relative;min-height:190px;padding:16px;border:1px solid var(--line);border-radius:10px;background:#fbfdff;overflow:hidden}.role-card::before{content:"";position:absolute;inset:0 auto 0 0;width:4px;background:var(--role-color,var(--blue))}.role-level{color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.role-card h3{margin:8px 0 6px;color:var(--navy);font-size:15px}.role-card p{margin:0;color:#596b80;font-size:11px;line-height:1.55}.scope{display:flex;flex-wrap:wrap;gap:5px;margin-top:12px}.scope span{padding:4px 7px;border-radius:999px;color:#38526b;background:#edf3f8;font-size:9.5px;font-weight:750}
    .profiles-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-end}.profiles-head label{display:grid;gap:5px;color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.05em}.profiles-head select{min-width:230px;padding:9px 32px 9px 10px;border:1px solid #cbd7e3;border-radius:8px;color:var(--navy);background:#fff;font:inherit;font-size:12px;font-weight:750}
    .profile-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:17px}.user-card{display:grid;grid-template-columns:54px 1fr;gap:12px;align-items:start;padding:15px;border:1px solid var(--line);border-radius:10px;background:#fff;transition:.18s ease}.user-card.is-preview{border-color:var(--teal);box-shadow:0 0 0 3px rgba(31,154,156,.12),0 10px 24px rgba(22,52,91,.1)}.avatar{display:grid;place-items:center;width:54px;height:54px;border-radius:14px;color:#fff;background:linear-gradient(145deg,var(--blue),var(--navy));font-size:16px;font-weight:900}.avatar.template{color:var(--navy);background:#e9f0f6}.user-card h3{margin:1px 0 3px;color:var(--navy);font-size:14px}.user-title{display:block;color:#607086;font-size:10.5px;line-height:1.4}.role-pill{display:inline-flex;margin-top:8px;padding:4px 7px;border-radius:999px;color:#0f6f70;background:#e7f7f5;font-size:9px;font-weight:850}.user-status{display:flex;align-items:center;gap:5px;margin-top:7px;color:#68778a;font-size:9.5px}.user-status::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--good)}.profile-actions{grid-column:1/-1;display:flex;gap:7px;margin-top:2px}.profile-actions button{padding:7px 9px;border:1px solid #cbd8e4;border-radius:7px;color:var(--blue);background:#fff;font:inherit;font-size:10px;font-weight:800;cursor:pointer}.profile-actions button:hover{border-color:var(--blue);background:#eff6fb}
    .preview-panel{display:none;margin-top:15px;padding:16px;border:1px solid rgba(31,154,156,.28);border-radius:10px;background:#f1faf8}.preview-panel.open{display:block}.preview-panel h3{margin:0;color:var(--navy);font-size:15px}.preview-meta{margin:5px 0 12px;color:var(--muted);font-size:11px}.preview-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.preview-columns h4{margin:0 0 7px;color:#52657a;font-size:10px;text-transform:uppercase;letter-spacing:.06em}.preview-list{display:grid;gap:6px;margin:0;padding:0;list-style:none}.preview-list li{padding:7px 9px;border-radius:7px;color:#38526b;background:#fff;font-size:11px}.preview-list.denied li{color:#855050;background:#fff7f7}
    .matrix-wrap{margin-top:16px;overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:1040px}th,td{padding:10px 9px;border-bottom:1px solid #e6ecf2;text-align:center;font-size:10px}th{position:sticky;top:0;color:#fff;background:var(--navy);font-size:9px;text-transform:uppercase;letter-spacing:.04em}th:first-child,td:first-child{text-align:left;position:sticky;left:0;z-index:1}td:first-child{color:var(--navy);background:#fbfdff;font-weight:800;min-width:190px}.yes,.limited,.no{display:inline-flex;align-items:center;justify-content:center;min-width:24px;height:24px;border-radius:7px;font-weight:900}.yes{color:#216947;background:#e7f5ed}.limited{color:#805a10;background:#fff4d8}.no{color:#9a5151;background:#fdeeee}.legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:10px;color:var(--muted);font-size:10px}.legend span{display:flex;align-items:center;gap:5px}
    .controls{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:16px}.control{padding:14px;border:1px solid var(--line);border-radius:9px;background:#fbfdff}.control strong{display:block;color:var(--navy);font-size:12px}.control p{margin:5px 0 0;color:var(--muted);font-size:10.5px;line-height:1.45}
    @@media(max-width:1180px){.role-grid{grid-template-columns:repeat(2,1fr)}.profile-grid{grid-template-columns:repeat(2,1fr)}.controls{grid-template-columns:repeat(2,1fr)}}
    @@media(max-width:900px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav,.side-note{display:none}.content{padding:18px}.topbar{align-items:flex-start;flex-direction:column}.profiles-head{align-items:flex-start;flex-direction:column}.profiles-head select{min-width:min(100%,330px)}.preview-columns{grid-template-columns:1fr}}
    @@media(max-width:620px){.role-grid,.profile-grid,.controls{grid-template-columns:1fr}.content{padding:14px}.panel{padding:16px}}
