            <article class="user-card" data-group="programme" data-role="GN Programme Manager" data-name="GN Programme Office" data-allowed="Operational dashboard|All membership applications|Member records|Reviewer assignments|Events and communications|Operational exports" data-denied="System permissions|Sole final decision authority"><div class="avatar template">GN</div><div><h3>GN Programme Office</h3><span class="user-title">Named staff account to be confirmed</span><span class="role-pill">GN Programme Manager</span><span class="user-status">Assignment required</span></div><div class="profile-actions"><button type="button" class="preview-user">Preview access</button></div></article>
